vec2 random2(vec2 p) {
    return fract(sin(vec2(dot(p,vec2(127.1,311.7)),
                         dot(p,vec2(269.5,183.3))))*43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f*f*(3.0-2.0*f);

    float a = dot(random2(i), f);
    float b = dot(random2(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));
    float c = dot(random2(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));
    float d = dot(random2(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));

    return mix(mix(a, b, u.x),
              mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 1.0;

    for(int i = 0; i < 6; i++) {
        value += amplitude * noise(p * frequency);
        frequency *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

float hexagonDistance(vec2 p) {
    p = abs(p);
    float c = dot(p, normalize(vec2(1.0, 1.73205)));
    c = max(c, p.x);
    return c;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0*fragCoord.xy-iResolution.xy) / iResolution.y;
    float a = atan(p.x,p.y);

    float r = hexagonDistance(p);

    float rotSpeed = 0.2;
    p = mat2(cos(iTime*rotSpeed), -sin(iTime*rotSpeed), 
             sin(iTime*rotSpeed), cos(iTime*rotSpeed)) * p;

    // Create a mask for the noise effect
    float noiseMask = smoothstep(0.6, 0.4, abs(r - 0.5));

    // Noise calculation with tighter bounds
    float noiseTime = iTime * 0.2;
    vec2 noisePos = p + vec2(noiseTime * 0.5, noiseTime * 0.3);
    float noiseValue = fbm(noisePos * 4.0) * noiseMask; // Higher frequency, masked

    // Apply distortion only near the hexagon edges
    float distortion = sin(iTime * 2.50 + r * 20.0) * 0.05;
    distortion += noiseValue * 0.15; // Reduced noise influence
    r += distortion * noiseMask; // Apply mask to distortion

    vec2 uv = vec2(0.0,r);
    uv = (2.0 * uv) -1.0;     

    // Modulate pulse with masked noise
    float pulse = cos(iTime * 1.0) * 0.5 + 1.0;
    pulse *= 1.0 + noiseValue * 0.3;
    float beamWidth = abs(5.0 / (40.0 * uv.y)) * pulse;

    vec3 color = vec3(1.0, 0.5, 0.5);
    vec3 horBeam = color * beamWidth;

    // Enhanced edge glow with noise
    float edgeGlow = smoothstep(0.8, 0.0, abs(r - 0.5) * 2.0);
    edgeGlow *= 1.0 + noiseValue * 0.5; // Noise affects glow intensity
    horBeam += color * edgeGlow * 0.15;

    // Fade out at the edges
    float fade = smoothstep(1.2, 0.8, r);
    horBeam *= fade;

    fragColor = vec4(horBeam, 1.0);
}
